import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.9.4 — View AI Credit Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/08-subscription-billing/3-9-4-view-ai-credit-tracking/spec.md","filePath":"feature/srs/08-subscription-billing/3-9-4-view-ai-credit-tracking/spec.md"}'),i={name:"feature/srs/08-subscription-billing/3-9-4-view-ai-credit-tracking/spec.md"};function c(r,e,n,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-9-4-—-view-ai-credit-tracking" tabindex="-1">FR 3.9.4 — View AI Credit Tracking <a class="header-anchor" href="#fr-3-9-4-—-view-ai-credit-tracking" aria-label="Permalink to &quot;FR 3.9.4 — View AI Credit Tracking&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.9.4</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-125</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View AI Credit Tracking</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Subscription &amp; Billing (<code>3.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-65</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>ai-credit-balance</code>, <code>credit-unification</code>, <code>workspace-credit-unification</code>, <code>member-credit</code>, <code>local-credit-seed</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide real-time, <code>BIGINT</code>-safe AI Credit balance and per-period consumption tracking across the Sidebar/AI Studio widget (<code>AiCreditBalance.tsx</code>), Agency Credit Console (<code>/agency/:agencyId/credit</code>), and Workspace AI headers. Unifies reporting on the single Agency wallet (<code>agency_credit_wallets</code>, <code>credit_grants</code>: <code>PLAN</code>, <code>PURCHASED</code>, <code>DEV_SEED</code>) and Workspace period budgets (<code>workspace_credit_limits</code>, <code>workspace_credit_usage</code>, <code>ai_credit_reservations</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner, Manager, Creator</code>, I want to execute <strong>View AI Credit Tracking</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-20, BR-65</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner, Manager, Creator</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Effective Balance &amp; Eligibility (<code>ai-credit-balance</code>, <code>workspace-credit-unification</code>):</strong> <code>Client</code> and outsiders are denied (<code>403</code>). <code>Owner</code> sees full Agency active grant balance (<code>PLAN</code> consumed before non-expiring <code>PURCHASED</code>, then local-only <code>DEV_SEED</code>); <code>Manager</code>/<code>Creator</code> see effective minimum of Agency available balance and their active Workspace remaining cap (<code>limit - used - held</code>). Sidebar widget displays <code>visible = true</code> only when eligible and never fabricates plan allowance as wallet balance.</li><li><strong>2. Four Billable Operations vs Free Actions (<code>DA-974</code>):</strong> Only <code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, and <code>VIDEO_GENERATE</code> consume Admin-configured credits (<code>ai_credit_operation_prices</code>). <code>CAPTION_VARIANTS</code> (including refine/adapt), <code>HASHTAG_GENERATE</code>, and <code>CHARACTER_SHEET</code> persist <code>unit_credits = 0</code> (<code>FREE_V1</code>).</li><li><strong>3. Held vs Settled Precision:</strong> <code>RESERVED</code> jobs (e.g., pending <code>VIDEO_GENERATE</code> or unknown-outcome timeouts awaiting reconciliation) report under <code>held</code> (<code>creditsHeld</code>), distinct from <code>SETTLED</code> (<code>used</code>), serialized as strings where needed for JavaScript <code>BIGINT</code> safety.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>subscription.credits.*</code>, <code>credit.balance.*</code>, <code>credit.usage.*</code>, <code>credit.workspace.*</code> in <code>src/i18n/locales/{vi,en}/subscription.json</code> &amp; <code>credit.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>components/billing/AiCreditBalance.tsx</code>, <code>pages/credit/index.tsx</code> (<code>CreditBalancePanel.tsx</code>, <code>CreditUsagePanel.tsx</code>, <code>WorkspaceCreditPanel.tsx</code>, <code>OwnerCreditView.tsx</code>) on Web and <code>src/screens/billing/AgencyCreditScreen.tsx</code>, <code>src/services/creditService.ts</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>components/billing/AiCreditBalance.tsx</code>, <code>pages/credit/index.tsx</code> (<code>CreditBalancePanel.tsx</code>, <code>CreditUsagePanel.tsx</code>, <code>WorkspaceCreditPanel.tsx</code>, <code>OwnerCreditView.tsx</code>)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/AgencyCreditScreen.tsx</code>, <code>src/services/creditService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/credits/summary?workspaceId={wid}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>CreditBalanceController.summary()</code> -&gt; <code>REPEATABLE_READ</code> snapshot returning <code>visible</code>, Agency available/held, and effective Workspace remaining</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/credit/balance</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>CreditUsageController.balance()</code> -&gt; breakdown of <code>planAvailable</code>, <code>purchasedAvailable</code>, <code>developmentAvailable</code>, <code>totalAvailable</code>, and <code>held</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/credit/workspaces</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>WorkspaceCreditController.list()</code> -&gt; <code>Owner</code> sees all Agency Workspaces; <code>Manager</code>/<code>Creator</code> see only their active Workspaces (<code>workspaceLimit</code>, <code>workspaceUsed</code>, <code>workspaceHeld</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/credit/usage/me &amp; /members/{memberId}/usage</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>CreditUsageController</code> -&gt; actor-attributed consumption &amp; per-operation breakdown (<code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/ai/credits</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiCaptionController</code> -&gt; Editor/Studio workspace credit readiness snapshot</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner, Manager, Creator</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-9-5-buy-credit/spec.html">FR 3.9.5 — Buy Credit</a> · <a href="./../3-9-6-set-credit/spec.html">FR 3.9.6 — Set Credit</a> · <a href="./../../09-admin-functions/3-10-10-view-ai-credit-price-list/spec.html">FR 3.10.10 — View AI Credit Price List</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const f=t(i,[["render",c]]);export{u as __pageData,f as default};
